import json
from pathlib import Path
D=Path(__file__).parent
files={n:json.loads((D/(n+'-patch.json')).read_text()) for n in ['root','models']}
changes=[]
def fix(name,sid,old,new,why):
 s=next(s for s in files[name]['sections'] if s['id']==sid)
 assert old in s['html'],(sid,old)
 s['html']=s['html'].replace(old,new)
 changes.append({'file':name,'section':sid,'before':old,'after':new,'reason':why})
p=files['root'];p['intro']=p['intro'].replace('正文沿业务路径讲，训练方法、接口参数和历史评测放在对应段落的展开项中。图保留原样；涉及车型差异或图中时序简写的地方，在图下说明适用条件。','先看每一步拿到什么、要作什么判断，再看它把什么交给下一步。遇到上汽和赛力斯做法不同的地方，按对应车型理解。')
fix('root','v39-map','它不必等云端全部完成。','赛力斯已激活时，两套识别同时运行；本地拿自己的识别结果计算候选，不以云端定稿到达为启动条件。','区分并行启动时机')
